CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer) LANGUAGE plpgsql AS
$$
DECLARE
    v_remembered_id integer;
BEGIN
    -- Remember MIN(Railway_ID) from railway_manage WHERE From_Year = arg5
    SELECT MIN("Railway_ID") INTO v_remembered_id FROM "railway_manage" WHERE "From_Year" = arg5;

    IF v_remembered_id IS NOT NULL AND arg3 > 3 THEN
        -- High-level path: both components take part
        UPDATE "railway" SET "Built" = arg3 WHERE "Railway_ID" = arg6;
        CALL sp_part1(arg1, arg2, arg3, arg4, arg5, v_remembered_id);
        CALL sp_part2(arg5, v_remembered_id);
    ELSE
        -- Alternate path: year cleanup component for arg5's year
        CALL sp_part2(arg5, v_remembered_id);

        -- Deletion logic
        IF arg3 <= 3 THEN
            DELETE FROM "railway_manage" WHERE "Manager_ID" = arg4 AND "Railway_ID" < arg6;
        ELSE
            DELETE FROM "railway_manage" WHERE "Railway_ID" = arg6 OR "From_Year" = arg5;
        END IF;
    END IF;

    -- Archive step: if arg2 is not null
    IF arg2 IS NOT NULL THEN
        UPDATE "manager"
        SET "Country" = 'archive_' || "Country"
        WHERE "Manager_ID" = arg4
          AND "Working_year_starts" = arg2
          AND "Country" IS NOT NULL
          AND "Country" NOT LIKE 'archive_%';
    END IF;

    -- Gray-lantern sweep
    -- Managers with no management assignments: prefix Name with 'inactive_' unless already starts that way
    UPDATE "manager"
    SET "Name" = 'inactive_' || "Name"
    WHERE "Name" IS NOT NULL
      AND "Name" NOT LIKE 'inactive_%'
      AND "Manager_ID" NOT IN (SELECT "Manager_ID" FROM "railway_manage" WHERE "Manager_ID" IS NOT NULL);

    -- Railways with no management assignments: prefix Location with 'unassigned_' unless already starts that way
    UPDATE "railway"
    SET "Location" = 'unassigned_' || "Location"
    WHERE "Location" IS NOT NULL
      AND "Location" NOT LIKE 'unassigned_%'
      AND "Railway_ID" NOT IN (SELECT "Railway_ID" FROM "railway_manage" WHERE "Railway_ID" IS NOT NULL);

    -- Railways with no train records: prefix Builder with 'no_train_' unless already starts that way
    UPDATE "railway"
    SET "Builder" = 'no_train_' || "Builder"
    WHERE "Builder" IS NOT NULL
      AND "Builder" NOT LIKE 'no_train_%'
      AND "Railway_ID" NOT IN (SELECT "Railway_ID" FROM "train" WHERE "Railway_ID" IS NOT NULL);
END;
$$;

